PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "journalapp_heroslide" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "subtitle" varchar(300) NOT NULL, "image" varchar(100) NOT NULL, "button_text" varchar(50) NOT NULL, "button_url" varchar(200) NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "is_active" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "journalapp_sitesettings" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "site_title" varchar(100) NOT NULL, "site_description" text NOT NULL, "logo" varchar(100) NULL, "favicon" varchar(100) NULL, "primary_color" varchar(20) NOT NULL, "secondary_color" varchar(20) NOT NULL, "footer_text" text NOT NULL, "contact_email" varchar(254) NOT NULL, "contact_phone" varchar(20) NOT NULL, "facebook_url" varchar(200) NOT NULL, "twitter_url" varchar(200) NOT NULL, "instagram_url" varchar(200) NOT NULL, "linkedin_url" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "journalapp_customuser" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "first_name" varchar(30) NOT NULL, "last_name" varchar(30) NOT NULL, "is_active" bool NOT NULL, "is_staff" bool NOT NULL, "date_joined" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "journalapp_customuser_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customuser_id" bigint NOT NULL REFERENCES "journalapp_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "journalapp_customuser_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customuser_id" bigint NOT NULL REFERENCES "journalapp_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "journalapp_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "journalapp_articlecategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "description" text NOT NULL, "is_default" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "journalapp_department" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "code" varchar(10) NOT NULL UNIQUE, "description" text NOT NULL, "cover_image" varchar(100) NULL, "journal_title" varchar(200) NOT NULL, "journal_description" text NOT NULL);
CREATE TABLE IF NOT EXISTS "journalapp_profile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "profile_picture" varchar(100) NULL, "is_editor" bool NOT NULL, "is_reviewer" bool NOT NULL, "department_id" bigint NULL REFERENCES "journalapp_department" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL UNIQUE REFERENCES "journalapp_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "bio" text NOT NULL);
CREATE TABLE IF NOT EXISTS "journalapp_review" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "comments" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "reviewer_id" bigint NOT NULL REFERENCES "journalapp_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "article_id" bigint NOT NULL REFERENCES "journalapp_article" ("id") DEFERRABLE INITIALLY DEFERRED, "decision" varchar(20) NOT NULL);
CREATE TABLE IF NOT EXISTS "journalapp_article" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "abstract" text NOT NULL, "content" text NOT NULL, "file" varchar(100) NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "published_at" datetime NULL, "author_id" bigint NOT NULL REFERENCES "journalapp_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "department_id" bigint NOT NULL REFERENCES "journalapp_department" ("id") DEFERRABLE INITIALLY DEFERRED, "category_id" bigint NOT NULL REFERENCES "journalapp_articlecategory" ("id") DEFERRABLE INITIALLY DEFERRED, "keywords" varchar(255) NOT NULL, "revised_document" varchar(100) NULL, "revision_notes" text NULL);
CREATE TABLE IF NOT EXISTS "journalapp_comment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "author_id" bigint NOT NULL REFERENCES "journalapp_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "article_id" bigint NOT NULL REFERENCES "journalapp_article" ("id") DEFERRABLE INITIALLY DEFERRED, "content" text NOT NULL);
CREATE TABLE IF NOT EXISTS "journalapp_archivedjournal" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "description" text NULL, "volume" varchar(50) NULL, "issue" varchar(50) NULL, "publication_date" date NOT NULL, "document" varchar(100) NOT NULL, "cover_image" varchar(100) NULL, "uploaded_at" datetime NOT NULL, "department_id" bigint NOT NULL REFERENCES "journalapp_department" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NULL REFERENCES "journalapp_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "featured" bool NOT NULL);
CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
CREATE INDEX "auth_group_permissions_permission_id_84c5c92e" ON "auth_group_permissions" ("permission_id");
CREATE UNIQUE INDEX "auth_permission_content_type_id_codename_01ab375a_uniq" ON "auth_permission" ("content_type_id", "codename");
CREATE INDEX "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");
CREATE UNIQUE INDEX "journalapp_customuser_groups_customuser_id_group_id_697b6dce_uniq" ON "journalapp_customuser_groups" ("customuser_id", "group_id");
CREATE INDEX "journalapp_customuser_groups_customuser_id_43be4c84" ON "journalapp_customuser_groups" ("customuser_id");
CREATE INDEX "journalapp_customuser_groups_group_id_b6f53d6d" ON "journalapp_customuser_groups" ("group_id");
CREATE UNIQUE INDEX "journalapp_customuser_user_permissions_customuser_id_permission_id_36c1a266_uniq" ON "journalapp_customuser_user_permissions" ("customuser_id", "permission_id");
CREATE INDEX "journalapp_customuser_user_permissions_customuser_id_c566ce4f" ON "journalapp_customuser_user_permissions" ("customuser_id");
CREATE INDEX "journalapp_customuser_user_permissions_permission_id_afe8b30a" ON "journalapp_customuser_user_permissions" ("permission_id");
CREATE INDEX "django_admin_log_content_type_id_c4bce8eb" ON "django_admin_log" ("content_type_id");
CREATE INDEX "django_admin_log_user_id_c564eba6" ON "django_admin_log" ("user_id");
CREATE INDEX "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");
CREATE INDEX "journalapp_profile_department_id_ec2c66c8" ON "journalapp_profile" ("department_id");
CREATE INDEX "journalapp_review_reviewer_id_26d8f7fc" ON "journalapp_review" ("reviewer_id");
CREATE INDEX "journalapp_review_article_id_a4b3f5b1" ON "journalapp_review" ("article_id");
CREATE INDEX "journalapp_article_author_id_98e8b8aa" ON "journalapp_article" ("author_id");
CREATE INDEX "journalapp_article_department_id_d93e0865" ON "journalapp_article" ("department_id");
CREATE INDEX "journalapp_article_category_id_961cd959" ON "journalapp_article" ("category_id");
CREATE INDEX "journalapp_comment_author_id_dde9e1e8" ON "journalapp_comment" ("author_id");
CREATE INDEX "journalapp_comment_article_id_6fe7ea67" ON "journalapp_comment" ("article_id");
CREATE INDEX "journalapp_archivedjournal_department_id_ec1172c1" ON "journalapp_archivedjournal" ("department_id");
CREATE INDEX "journalapp_archivedjournal_uploaded_by_id_d4e51e16" ON "journalapp_archivedjournal" ("uploaded_by_id");
COMMIT;
